-- 0228 — Academy, niveau 2 « Analyse fondamentale » réécrit (2026-11-14).
--
-- Les sept leçons précédentes étaient des gabarits générés (« Synthèse
-- éditoriale », « Réécriture structurée »), sans quiz, avec une leçon 4
-- manquante et les leçons 8 à 10 tassées en une seule. Elles passent au
-- format du niveau 1 : dix leçons, chiffres de marché lus en base (blocs
-- donnees_reelles, dont la nouvelle vue « ratios »), exemples annoncés comme
-- pédagogiques, 5 questions par leçon, avertissement.
-- Nouvelle leçon 4 : « Analyser une banque cotée ».
-- Source : frontend/lib/academy/contenus/niveau2/*.json (testés).
-- Sauvegarde avant écriture : docs/academy/sauvegardes/2026-11-14-academy-niveau-2-fondamental.json
--
-- Progression : academy_progress est indexée par POSITION de leçon. L’ancienne
-- position 3 (leçon 5) devient 4, etc. : on décale de +1 les positions ≥ 3,
-- dans la même transaction et sous la même garde (7 leçons), pour que la
-- migration rejouée ne décale pas deux fois.
-- Aucune donnée personnelle créée ; une seule ligne de progression concernée
-- au 2026-11-14.

do $do$
declare
  v_id uuid;
begin
  select id into v_id from public.academy_courses
   where slug = 'academy-niveau-2-fondamental'
     and jsonb_array_length(content->'lessons') = 7;
  if v_id is null then
    raise notice '0228 : niveau 2 déjà réécrit (ou introuvable), rien à faire';
    return;
  end if;

  update public.academy_progress
     set lesson_idx = lesson_idx + 1
   where course_id = v_id and lesson_idx >= 3;

  update public.academy_courses
     set content = jsonb_set(jsonb_set(content, '{lessons}', $wb$[{"titre": "Leçon 1 — Lire un rapport annuel", "module": "Module 1 — Lire et analyser une entreprise", "categorie": "fundamental", "duree_min": 12, "sous_titre": "Trois tableaux, un rapport des commissaires aux comptes, et un ordre de lecture qui évite de se perdre.", "resume": "Une société cotée publie chaque année ses états financiers : bilan, compte de résultat, tableau des flux de trésorerie et notes. Cette leçon montre où les trouver, ce que dit chaque tableau, dans quel ordre les lire et quels signaux doivent vous faire ralentir.", "sections": [{"type": "definition", "titre": "Les quatre pièces d’un rapport annuel", "contenu": "Les sociétés de la BRVM tiennent leurs comptes selon le SYSCOHADA révisé ; les banques suivent le plan comptable bancaire de l’UMOA. Le vocabulaire diffère un peu, la logique est la même.\nChaque pièce répond à une question différente. Les lire ensemble évite les conclusions hâtives.", "points": [{"titre": "Le bilan", "detail": "Une photographie à la date de clôture : ce que la société possède (actif) et comment c’est financé (passif : fonds propres et dettes).", "verifier": "Le total des capitaux propres, et sa variation d’une année sur l’autre."}, {"titre": "Le compte de résultat", "detail": "Le film de l’année : chiffre d’affaires, charges, résultat d’exploitation, résultat net.", "verifier": "Le résultat d’exploitation, avant les éléments hors activités ordinaires."}, {"titre": "Le tableau des flux de trésorerie", "detail": "L’argent réellement entré et sorti : activité, investissements, financement (dont les dividendes versés).", "verifier": "Le flux des activités opérationnelles : positif, et proche du résultat ?"}, {"titre": "Les notes et le rapport des commissaires", "detail": "Les notes détaillent les postes ; le rapport des commissaires aux comptes dit si les comptes sont certifiés, avec ou sans réserve.", "verifier": "Le mot « réserve » ou « observation » dans le rapport des commissaires."}]}, {"type": "importance", "titre": "Le mécanisme : du chiffre d’affaires au dividende", "contenu": "Le résultat net appartient aux actionnaires. L’assemblée générale décide d’en distribuer une partie (le dividende) et de garder le reste en réserves, ce qui augmente les fonds propres.", "flux": [{"titre": "Ventes", "detail": "Chiffre d’affaires de l’année", "icone": "entreprise"}, {"titre": "Résultat net", "detail": "Après charges, intérêts et impôt", "icone": "benefices"}, {"titre": "Assemblée générale", "detail": "Vote l’affectation du résultat", "icone": "decision"}, {"titre": "Dividende", "detail": "Versé aux actionnaires", "icone": "paiement"}, {"titre": "Réserves", "detail": "Le reste renforce les fonds propres", "icone": "actionnaires"}]}, {"type": "cas", "titre": "Un ordre de lecture en cinq étapes", "contenu": "Lire de la première à la dernière page fait perdre l’essentiel. Cet ordre va du plus important au détail.", "etapes": [{"titre": "Le rapport des commissaires aux comptes", "detail": "Des comptes certifiés sans réserve sont le point de départ. Une réserve se lit avant tout le reste.", "cle": true}, {"titre": "Le compte de résultat sur deux exercices", "detail": "Le chiffre d’affaires progresse-t-il ? Le résultat suit-il, ou dépend-il d’un élément exceptionnel ?"}, {"titre": "Le tableau des flux", "detail": "Un bénéfice qui ne devient jamais trésorerie est un signal : créances qui gonflent, stocks qui s’accumulent."}, {"titre": "Le bilan", "detail": "Les fonds propres augmentent-ils ? La dette financière est-elle supportable face au résultat ?"}, {"titre": "L’affectation du résultat", "detail": "Quelle part du bénéfice est distribuée, et quelle part est gardée pour investir."}]}, {"type": "importance", "titre": "Où trouver les comptes", "contenu": "Les sociétés cotées publient leurs états financiers annuels, puis des rapports d’activité trimestriels et semestriels. Les documents officiels sont diffusés par la BRVM.", "tableau": {"colonnes": ["Document", "Fréquence", "Ce qu’on y trouve"], "lignes": [["États financiers annuels", "Une fois par an", "Bilan, compte de résultat, flux, affectation du résultat"], ["Rapport des commissaires aux comptes", "Une fois par an", "Certification des comptes, réserves éventuelles"], ["Rapport d’activité", "Trimestre, semestre", "Chiffre d’affaires, résultat, commentaires de la direction"], ["Avis et communiqués", "Selon les événements", "Dividende, assemblée générale, opération sur le capital"]], "note": "Sur WestBourse, chaque fiche société regroupe ses comptes, ses publications et ses dividendes."}}, {"type": "piege", "titre": "Les pièges de lecture", "contenu": "Un rapport annuel est un document que la société rédige sur elle-même. Les chiffres sont contrôlés ; les commentaires restent de la communication.", "points": [{"titre": "Confondre provisoire et définitif", "detail": "Certains états sont publiés « provisoires, non approuvés par l’assemblée générale ». Ils peuvent encore changer.", "verifier": "La mention en tête du document."}, {"titre": "Prendre un résultat exceptionnel pour une tendance", "detail": "Une cession d’actif gonfle le résultat d’une seule année. Le résultat d’exploitation la neutralise.", "verifier": "La ligne « résultat hors activités ordinaires »."}, {"titre": "Comparer des périmètres différents", "detail": "Comptes sociaux (la société seule) et comptes consolidés (avec ses filiales) ne se comparent pas.", "verifier": "Le titre exact du document."}, {"titre": "Oublier l’unité", "detail": "Certains tableaux sont en millions, d’autres en FCFA, plus rarement en devise étrangère.", "verifier": "L’unité indiquée sous le titre du tableau."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Lire un rapport annuel, c’est répondre à quatre questions dans l’ordre.", "points": [{"titre": "Les comptes sont-ils certifiés sans réserve ?"}, {"titre": "Le résultat vient-il de l’activité courante ?"}, {"titre": "Ce résultat devient-il de la trésorerie ?"}, {"titre": "Les fonds propres et la dette évoluent-ils dans le bon sens ?"}]}], "quiz": [{"question": "Quel document indique si les comptes sont certifiés ?", "options": ["Le compte de résultat", "Le rapport des commissaires aux comptes", "Le rapport d’activité trimestriel", "L’avis de convocation à l’assemblée générale"], "correct": 1, "explication": "Les commissaires aux comptes certifient les comptes, avec ou sans réserve. C’est la première chose à lire."}, {"question": "Une société affiche un résultat net en forte hausse, mais son flux de trésorerie opérationnel est négatif. Que vérifier en priorité ?", "options": ["Rien, le résultat suffit", "L’évolution des créances clients et des stocks", "Le nombre d’administrateurs", "Le cours de l’action"], "correct": 1, "explication": "Un bénéfice qui ne devient pas trésorerie vient souvent de créances ou de stocks qui augmentent. Ce n’est pas forcément grave, mais il faut comprendre pourquoi."}, {"question": "Que montre le bilan ?", "options": ["Les ventes de l’année", "Ce que la société possède et comment c’est financé, à une date donnée", "L’argent entré et sorti dans l’année", "Le cours moyen de l’action"], "correct": 1, "explication": "Le bilan est une photographie à la date de clôture : actif d’un côté, fonds propres et dettes de l’autre."}, {"question": "Pourquoi regarder le résultat d’exploitation, pas seulement le résultat net ?", "options": ["Il est toujours plus élevé", "Il exclut les éléments exceptionnels et financiers : il montre l’activité courante", "Il inclut le dividende", "Il est le seul certifié"], "correct": 1, "explication": "Le résultat d’exploitation reflète l’activité courante. Une cession exceptionnelle peut gonfler le résultat net d’une seule année."}, {"question": "Des états financiers publiés « provisoires, non approuvés par l’assemblée générale » :", "options": ["Ne peuvent plus changer", "Peuvent encore être modifiés avant leur approbation", "Sont toujours faux", "Ne sont pas publics"], "correct": 1, "explication": "Des comptes provisoires peuvent évoluer jusqu’à l’assemblée générale. Ils sont utiles, à condition de le savoir."}], "liens": [{"label": "Les fondamentaux de toutes les sociétés", "href": "/fondamentaux"}, {"label": "Les dossiers valeur", "href": "/rapports/dossiers"}, {"label": "Les sociétés cotées", "href": "/societes"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Quel document indique si les comptes sont certifiés ?", "options": ["Le compte de résultat", "Le rapport des commissaires aux comptes", "Le rapport d’activité trimestriel", "L’avis de convocation à l’assemblée générale"], "correct": 1, "explication": "Les commissaires aux comptes certifient les comptes, avec ou sans réserve. C’est la première chose à lire."}}, {"titre": "Leçon 2 — Le PER : évaluer la cherté d’une action", "module": "Module 1 — Lire et analyser une entreprise", "categorie": "evaluation", "duree_min": 11, "sous_titre": "Combien d’années de bénéfices vous payez en achetant une action, et pourquoi ce chiffre ne se lit jamais seul.", "resume": "Le PER rapporte le cours d’une action à son bénéfice par action. Il dit combien le marché paie pour un franc de bénéfice. Cette leçon montre comment le calculer, comment le lire sur de vraies valeurs de la BRVM, et ses limites.", "sections": [{"type": "definition", "titre": "Trois formules", "contenu": "Le PER (price earnings ratio) se calcule à partir du bénéfice par action, le BPA. Les exemples ci-dessous sont pédagogiques.", "formules": [{"nom": "Bénéfice par action (BPA)", "expression": "Résultat net ÷ Nombre d’actions", "exemple": "2 000 000 000 ÷ 10 000 000 = 200 FCFA"}, {"nom": "PER", "expression": "Cours de l’action ÷ BPA", "exemple": "3 000 ÷ 200 = 15 (on dit « 15 fois les bénéfices »)"}, {"nom": "Rendement bénéficiaire", "expression": "1 ÷ PER", "exemple": "1 ÷ 15 ≈ 6,7 % : le bénéfice rapporté au prix payé"}]}, {"type": "importance", "titre": "Ce que le PER raconte", "contenu": "Un PER de 15 signifie qu’au bénéfice actuel, il faudrait 15 ans de bénéfices pour « rembourser » le prix de l’action.\nUn PER élevé traduit souvent une attente de croissance ; un PER faible peut signaler une société délaissée, ou une société en difficulté. Le chiffre seul ne tranche pas.", "stats": [{"label": "PER faible", "valeur": "Moins de 8", "detail": "Décote, ou méfiance du marché : à expliquer"}, {"label": "PER intermédiaire", "valeur": "8 à 15", "detail": "Zone fréquente pour une société mature"}, {"label": "PER élevé", "valeur": "Plus de 20", "detail": "Croissance attendue, ou bénéfice temporairement bas"}]}, {"type": "cas", "titre": "Sur la BRVM : trois opérateurs télécoms", "reel": true, "contenu": "Comparer des sociétés du même secteur est la seule comparaison qui ait un sens. Les ratios ci-dessous sont recalculés à l’ouverture de la leçon, à partir du dernier cours et des derniers comptes publiés.", "donnees_reelles": {"vue": "ratios", "codes": ["SNTS", "ORAC", "ONTBF"]}}, {"type": "importance", "titre": "Les trois PER qu’on rencontre", "contenu": "Le même mot recouvre des calculs différents. Toujours demander : sur quel bénéfice ?", "tableau": {"colonnes": ["PER", "Bénéfice utilisé", "Usage"], "lignes": [["Historique", "Dernier exercice publié", "Le plus fiable : chiffres certifiés"], ["Glissant (12 mois)", "Quatre derniers trimestres publiés", "Plus récent, quand la société publie des comptes intermédiaires"], ["Prévisionnel", "Bénéfice estimé de l’année en cours", "Rare à la BRVM : aucune estimation n’est certifiée"]], "note": "WestBourse utilise le PER historique, sur le résultat consolidé quand la société publie des comptes consolidés."}}, {"type": "piege", "titre": "Quand le PER trompe", "contenu": "Le PER est simple à calculer et facile à mal lire.", "points": [{"titre": "Le bénéfice exceptionnel", "detail": "Une plus-value de cession gonfle le bénéfice d’une année : le PER paraît bas, à tort.", "verifier": "Le résultat d’exploitation a-t-il suivi ?"}, {"titre": "La perte", "detail": "Avec un résultat négatif, le PER n’a pas de sens : il ne faut pas le lire comme « très bas ».", "verifier": "Le signe du résultat net."}, {"titre": "Le piège de la valeur", "detail": "Un PER bas sur une société dont les bénéfices baissent d’année en année n’est pas une affaire.", "verifier": "La tendance du bénéfice sur 3 à 5 ans."}, {"titre": "Comparer deux secteurs", "detail": "Une banque et une société de distribution n’ont pas les mêmes PER « normaux ».", "verifier": "La médiane du secteur."}, {"titre": "Le nombre d’actions qui change", "detail": "Après un fractionnement, le BPA se divise : il faut le comparer avec le bon nombre de titres.", "verifier": "Les opérations sur titres de la société."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Le PER est un point de départ, pas un verdict.", "points": [{"titre": "PER = cours ÷ bénéfice par action"}, {"titre": "Il se compare dans un même secteur, et dans le temps pour une même société"}, {"titre": "Il n’a pas de sens en cas de perte"}, {"titre": "Un PER bas demande une explication avant d’être une opportunité"}]}], "quiz": [{"question": "Une action cote 4 500 FCFA ; son bénéfice par action est de 300 FCFA. Quel est son PER ?", "options": ["10", "15", "20", "1 350"], "correct": 1, "explication": "4 500 ÷ 300 = 15."}, {"question": "Une société a gagné 5 milliards et compte 20 millions d’actions. Quel est son BPA ?", "options": ["25 FCFA", "250 FCFA", "2 500 FCFA", "4 FCFA"], "correct": 1, "explication": "5 000 000 000 ÷ 20 000 000 = 250 FCFA par action."}, {"question": "Une société a un PER de 4, nettement sous ses concurrents. Quelle est la bonne réaction ?", "options": ["Acheter immédiatement", "Chercher pourquoi : bénéfice exceptionnel, bénéfices en baisse, risque particulier", "Vendre immédiatement", "Ignorer le PER"], "correct": 1, "explication": "Un PER très bas peut être une opportunité, ou le signe d’un problème. Il faut l’expliquer avant de conclure."}, {"question": "Avec quelle société comparer le PER d’un opérateur télécom ?", "options": ["Une banque", "Un autre opérateur télécom", "Une société agricole", "L’indice BRVM Composite seul"], "correct": 1, "explication": "Les PER « normaux » varient d’un secteur à l’autre. La comparaison utile se fait dans le même secteur."}, {"question": "Une société affiche une perte. Que vaut son PER ?", "options": ["Il est très attractif", "Il n’a pas de sens", "Il vaut zéro", "Il vaut 100"], "correct": 1, "explication": "Avec un bénéfice négatif, le PER n’a pas de signification économique."}], "liens": [{"label": "La valorisation de toutes les valeurs", "href": "/premium/valorisation"}, {"label": "Comparer des actions", "href": "/actions/compare"}, {"label": "Les fondamentaux", "href": "/fondamentaux"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Une action cote 4 500 FCFA ; son bénéfice par action est de 300 FCFA. Quel est son PER ?", "options": ["10", "15", "20", "1 350"], "correct": 1, "explication": "4 500 ÷ 300 = 15."}}, {"titre": "Leçon 3 — P/B, ROE et rendement : les ratios complémentaires", "module": "Module 1 — Lire et analyser une entreprise", "categorie": "evaluation", "duree_min": 11, "sous_titre": "Ce que vaut l’entreprise dans ses livres, ce qu’elle rapporte sur ses fonds propres, et le lien entre les deux.", "resume": "Le PER ne regarde que le bénéfice. Le P/B compare le cours aux fonds propres, le ROE mesure la rentabilité de ces fonds propres, et le rendement du dividende dit ce que vous touchez. Lus ensemble, ces ratios disent si un prix élevé est justifié.", "sections": [{"type": "definition", "titre": "Trois ratios, trois questions", "contenu": "Les exemples chiffrés sont pédagogiques.", "formules": [{"nom": "Price to book (P/B)", "expression": "Capitalisation ÷ Fonds propres", "exemple": "60 Md ÷ 40 Md = 1,5 : le marché paie 1,5 fois la valeur comptable"}, {"nom": "Rentabilité des fonds propres (ROE)", "expression": "Résultat net ÷ Fonds propres", "exemple": "8 Md ÷ 40 Md = 20 %"}, {"nom": "Rendement du dividende", "expression": "Dividende par action ÷ Cours", "exemple": "180 ÷ 3 000 = 6 %"}]}, {"type": "importance", "titre": "Le lien qui explique tout", "contenu": "Ces ratios ne sont pas indépendants : le P/B est égal au PER multiplié par le ROE.\nUne société très rentable mérite un P/B élevé. Un P/B élevé avec un ROE faible, en revanche, demande une explication.", "formules": [{"nom": "P/B = PER × ROE", "expression": "(Cours ÷ BPA) × (BPA ÷ Fonds propres par action)", "exemple": "PER 10 × ROE 25 % = P/B de 2,5"}], "stats": [{"label": "P/B inférieur à 1", "valeur": "Sous la valeur comptable", "detail": "Décote : actifs mal valorisés, ou rentabilité jugée faible"}, {"label": "ROE de 15 à 25 %", "valeur": "Rentabilité solide", "detail": "À comparer au secteur et au coût de la dette"}, {"label": "Taux de distribution", "valeur": "Dividende ÷ Bénéfice", "detail": "Proche de 100 % : peu de bénéfice gardé pour investir"}]}, {"type": "cas", "titre": "Sur la BRVM : des profils très différents", "reel": true, "contenu": "Une société peut afficher un P/B très élevé parce qu’elle distribue presque tout son bénéfice : ses fonds propres restent petits, et son ROE devient très élevé. Une autre cote sous sa valeur comptable. Les deux situations demandent une lecture, pas un réflexe.", "donnees_reelles": {"vue": "ratios", "codes": ["NTLC", "PALC", "SNTS", "SGBC"]}}, {"type": "cas", "titre": "Une lecture croisée", "contenu": "Exemple pédagogique : deux sociétés au même PER de 12 ne se valent pas.", "tableau": {"colonnes": ["Ratio", "Société A", "Société B"], "lignes": [["PER", "12", "12"], ["ROE", "25 %", "6 %"], ["P/B (= PER × ROE)", "3,0", "0,7"], ["Lecture", "Rentable : le P/B élevé se justifie", "Peu rentable : la décote s’explique"]], "note": "Le même PER cache deux réalités : c’est le ROE qui fait la différence."}}, {"type": "piege", "titre": "Les erreurs fréquentes", "contenu": "Chaque ratio a son angle mort.", "points": [{"titre": "Un ROE gonflé par la dette", "detail": "Une société très endettée a peu de fonds propres : son ROE paraît excellent, son risque est élevé aussi.", "verifier": "Le rapport dette financière ÷ fonds propres."}, {"titre": "Un rendement élevé par chute du cours", "detail": "Le rendement monte quand le cours baisse. Un rendement de 12 % peut annoncer un dividende qui sera réduit.", "verifier": "Le taux de distribution et la tendance du bénéfice."}, {"titre": "Un P/B lu pour une société de services", "detail": "Une entreprise qui a peu d’actifs physiques a naturellement un P/B élevé.", "verifier": "La nature des actifs du bilan."}, {"titre": "Des fonds propres négatifs", "detail": "Après des pertes accumulées, P/B et ROE n’ont plus de sens.", "verifier": "Le signe des capitaux propres."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Un ratio seul ne dit rien ; deux ratios ensemble commencent à raconter.", "points": [{"titre": "P/B = capitalisation ÷ fonds propres"}, {"titre": "ROE = résultat ÷ fonds propres"}, {"titre": "P/B = PER × ROE : un P/B élevé se justifie par un ROE élevé"}, {"titre": "Un rendement très élevé se vérifie avant de se célébrer"}]}], "quiz": [{"question": "Une société a 50 milliards de fonds propres et a gagné 10 milliards. Quel est son ROE ?", "options": ["5 %", "20 %", "50 %", "500 %"], "correct": 1, "explication": "10 ÷ 50 = 20 %."}, {"question": "Une société a un PER de 8 et un ROE de 25 %. Quel est son P/B ?", "options": ["0,32", "2", "3,1", "33"], "correct": 1, "explication": "P/B = PER × ROE = 8 × 0,25 = 2."}, {"question": "Une action cote 2 000 FCFA et verse 140 FCFA de dividende. Quel est son rendement ?", "options": ["1,4 %", "7 %", "14 %", "70 %"], "correct": 1, "explication": "140 ÷ 2 000 = 7 %."}, {"question": "Pourquoi un ROE très élevé n’est-il pas toujours une bonne nouvelle ?", "options": ["Il est toujours faux", "Il peut venir de fonds propres très faibles, à cause d’une dette importante ou de pertes passées", "Il réduit le dividende", "Il n’existe pas à la BRVM"], "correct": 1, "explication": "Un ROE élevé avec peu de fonds propres peut cacher un endettement important. Il faut regarder la structure du bilan."}, {"question": "Une action cote sous sa valeur comptable (P/B inférieur à 1). Que faut-il en conclure ?", "options": ["C’est forcément une affaire", "Il faut chercher pourquoi : rentabilité faible, actifs douteux, ou simple désintérêt du marché", "La société va faire faillite", "Le ratio est faux"], "correct": 1, "explication": "Une décote peut être une opportunité ou refléter une rentabilité faible. Le ROE aide à trancher."}], "liens": [{"label": "La valorisation de toutes les valeurs", "href": "/premium/valorisation"}, {"label": "Les dividendes", "href": "/dividendes"}, {"label": "Les fondamentaux", "href": "/fondamentaux"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Une société a 50 milliards de fonds propres et a gagné 10 milliards. Quel est son ROE ?", "options": ["5 %", "20 %", "50 %", "500 %"], "correct": 1, "explication": "10 ÷ 50 = 20 %."}}, {"titre": "Leçon 4 — Analyser une banque cotée", "module": "Module 1 — Lire et analyser une entreprise", "categorie": "fundamental", "duree_min": 12, "sous_titre": "Une valeur sur trois à la BRVM est une banque ou une société financière. Elles se lisent avec leurs propres indicateurs.", "resume": "Une banque ne vend pas de produits : elle prête l’argent de ses déposants. Son chiffre d’affaires s’appelle le produit net bancaire, son risque principal le coût du risque, sa solidité se mesure par la solvabilité. Cette leçon donne la grille de lecture propre aux banques.", "sections": [{"type": "definition", "titre": "Le compte de résultat d’une banque", "contenu": "Une banque gagne la différence entre ce que lui rapportent ses prêts et ce que lui coûtent ses ressources, plus des commissions.", "flux": [{"titre": "Produit net bancaire", "detail": "Marge d’intérêts + commissions : le « chiffre d’affaires »", "icone": "piece"}, {"titre": "Frais généraux", "detail": "Salaires, agences, informatique", "icone": "entreprise"}, {"titre": "Coût du risque", "detail": "Prêts qui ne seront pas remboursés", "icone": "graphique"}, {"titre": "Résultat net", "detail": "Après impôt", "icone": "benefices"}]}, {"type": "importance", "titre": "Les quatre indicateurs d’une banque", "contenu": "Les formules sont pédagogiques ; les banques publient elles-mêmes la plupart de ces indicateurs dans leur rapport d’activité.", "formules": [{"nom": "Coefficient d’exploitation", "expression": "Frais généraux ÷ Produit net bancaire", "exemple": "40 ÷ 100 = 40 % : plus il est bas, plus la banque est efficace"}, {"nom": "Coût du risque", "expression": "Dotations nettes aux provisions pour créances douteuses", "exemple": "Il se compare au produit net bancaire et à l’encours de crédits"}, {"nom": "ROE", "expression": "Résultat net ÷ Fonds propres", "exemple": "Une banque bien gérée vise souvent 15 à 25 %"}], "points": [{"titre": "La solvabilité", "detail": "Les fonds propres réglementaires rapportés aux risques pris. La réglementation bancaire de l’UMOA fixe un minimum : une banque doit le respecter avec une marge.", "verifier": "Le ratio publié dans le rapport d’activité."}]}, {"type": "cas", "titre": "Un exemple publié : la SIB en 2025", "contenu": "La Société Ivoirienne de Banque a publié ces indicateurs dans son rapport d’activité 2025 (avril 2026). Ce sont des chiffres datés : ils décrivent l’exercice 2025, pas la situation d’aujourd’hui.", "stats": [{"label": "Produit net bancaire 2025", "valeur": "108,7 Md FCFA", "detail": "Contre 102,8 Md en 2024 (+6 %)"}, {"label": "Coefficient d’exploitation", "valeur": "38,59 %", "detail": "Contre 39,05 % en 2024"}, {"label": "Coût du risque", "valeur": "3,6 Md FCFA", "detail": "Contre 5,2 Md en 2024 (−30 %)"}, {"label": "Résultat net 2025", "valeur": "55,6 Md FCFA", "detail": "Contre 50,2 Md en 2024 (+11 %)"}, {"label": "ROE publié", "valeur": "27,16 %", "detail": "Rapport d’activité 2025 de la SIB"}, {"label": "Solvabilité", "valeur": "Supérieure à 14 %", "detail": "Selon la banque, au-dessus du seuil réglementaire"}]}, {"type": "cas", "titre": "Sur la BRVM : quatre banques comparées", "reel": true, "contenu": "Pour une banque, le P/B est souvent plus parlant que le PER : ses actifs sont des prêts, inscrits au bilan à leur valeur. Les ratios sont recalculés à l’ouverture de la leçon.", "donnees_reelles": {"vue": "ratios", "codes": ["SGBC", "BOAC", "NSBC", "SIBC"]}}, {"type": "piege", "titre": "Ce qu’il ne faut pas appliquer à une banque", "contenu": "Plusieurs outils pensés pour l’industrie ne fonctionnent pas sur une banque.", "points": [{"titre": "La dette n’est pas un défaut", "detail": "Les dépôts des clients sont, comptablement, une dette. Un ratio d’endettement « classique » n’a pas de sens.", "verifier": "La solvabilité, à la place."}, {"titre": "Les scores de faillite industriels", "detail": "Le score d’Altman ou le F-Score de Piotroski sont construits pour des sociétés non financières. WestBourse ne les affiche pas pour les banques.", "verifier": "La mention « non applicable » sur la fiche."}, {"titre": "Un coût du risque anormalement bas", "detail": "Une année sans provisions peut précéder une année de rattrapage.", "verifier": "La moyenne sur trois à cinq ans."}, {"titre": "Banque et société de financement", "detail": "Leurs métiers et leurs ratios diffèrent, même si elles sont classées dans le même secteur.", "verifier": "L’activité exacte de la société."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Pour une banque, quatre chiffres d’abord.", "points": [{"titre": "Le produit net bancaire et sa progression"}, {"titre": "Le coefficient d’exploitation : l’efficacité"}, {"titre": "Le coût du risque : la qualité des prêts"}, {"titre": "La solvabilité et le ROE : la solidité et la rentabilité"}]}], "quiz": [{"question": "Comment s’appelle le « chiffre d’affaires » d’une banque ?", "options": ["Le résultat d’exploitation", "Le produit net bancaire", "Le coût du risque", "La capitalisation"], "correct": 1, "explication": "Le produit net bancaire regroupe la marge d’intérêts et les commissions."}, {"question": "Une banque a 120 Md de produit net bancaire et 48 Md de frais généraux. Quel est son coefficient d’exploitation ?", "options": ["25 %", "40 %", "60 %", "250 %"], "correct": 1, "explication": "48 ÷ 120 = 40 %."}, {"question": "Que mesure le coût du risque ?", "options": ["Le prix de l’action", "Les pertes probables sur les prêts accordés", "Les salaires", "Le dividende"], "correct": 1, "explication": "Le coût du risque enregistre les prêts qui ne seront probablement pas remboursés."}, {"question": "Pourquoi un ratio d’endettement classique n’a-t-il pas de sens pour une banque ?", "options": ["Les banques n’ont pas de dettes", "Les dépôts des clients sont comptablement des dettes : c’est son métier", "Il est interdit par la loi", "Il est toujours nul"], "correct": 1, "explication": "Le métier de la banque consiste à collecter des ressources pour prêter. On mesure sa solidité par la solvabilité."}, {"question": "Pour comparer des banques cotées, quel ratio de valorisation est souvent le plus parlant ?", "options": ["Le P/B, lu avec le ROE", "Le nombre d’agences", "Le volume d’échanges", "La date de création"], "correct": 0, "explication": "Les actifs d’une banque sont des prêts inscrits à leur valeur au bilan : le P/B, lu avec le ROE, est très utilisé."}], "liens": [{"label": "Les secteurs", "href": "/secteurs"}, {"label": "La valorisation de toutes les valeurs", "href": "/premium/valorisation"}, {"label": "Comparer des actions", "href": "/actions/compare"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Comment s’appelle le « chiffre d’affaires » d’une banque ?", "options": ["Le résultat d’exploitation", "Le produit net bancaire", "Le coût du risque", "La capitalisation"], "correct": 1, "explication": "Le produit net bancaire regroupe la marge d’intérêts et les commissions."}}, {"titre": "Leçon 5 — Diversification et allocation d’actifs", "module": "Module 2 — Construire son portefeuille", "categorie": "general", "duree_min": 11, "sous_titre": "Ne pas tout perdre à cause d’une seule société : combien de lignes, quels secteurs, quels pays.", "resume": "Diversifier, c’est répartir son argent pour qu’une mauvaise nouvelle sur une société ne ruine pas tout le portefeuille. À la BRVM, la diversification a des limites particulières : peu de sociétés, des secteurs concentrés, une liquidité inégale. Cette leçon donne des règles simples et vérifiables.", "sections": [{"type": "definition", "titre": "Deux risques différents", "contenu": "Le risque d’un portefeuille a deux sources. La diversification ne supprime que la première.", "points": [{"titre": "Le risque propre à une société", "detail": "Un mauvais résultat, un litige, un dirigeant qui part. Il se réduit en multipliant les lignes."}, {"titre": "Le risque de marché", "detail": "Une crise régionale, une hausse des taux, un recul général. Il touche toutes les actions à la fois : la diversification ne l’efface pas."}]}, {"type": "importance", "titre": "Combien de lignes ?", "contenu": "Les études menées sur les grands marchés montrent que l’essentiel du risque propre disparaît entre 10 et 20 lignes. Le graphique de la leçon illustre cette courbe avec des valeurs d’exemple.\nÀ la BRVM, avec une cinquantaine de sociétés et des secteurs concentrés, viser 8 à 15 lignes réparties sur plusieurs secteurs est un repère raisonnable."}, {"type": "importance", "titre": "Les quatre dimensions de la répartition", "contenu": "Une bonne répartition se vérifie sur quatre axes, pas seulement sur le nombre de lignes.", "tableau": {"colonnes": ["Dimension", "Question", "Repère"], "lignes": [["Société", "Quel poids pèse ma première ligne ?", "Rarement plus de 15 à 20 % du portefeuille"], ["Secteur", "Suis-je trop exposé aux banques ?", "Pas plus d’un tiers sur un seul secteur"], ["Pays", "Mes sociétés dépendent-elles d’une seule économie ?", "Répartir entre plusieurs pays de l’UEMOA"], ["Classe d’actifs", "Ai-je des obligations pour amortir les chocs ?", "Selon l’horizon et la tolérance au risque"]], "note": "Ces repères sont des ordres de grandeur pédagogiques, pas des règles réglementaires."}}, {"type": "cas", "titre": "Sur la BRVM : deux indices", "reel": true, "contenu": "L’indice BRVM Composite pondère les sociétés par leur capitalisation boursière : quelques grandes valeurs y pèsent lourd. Suivre un indice concentré n’est pas la même chose qu’être diversifié.", "donnees_reelles": {"vue": "indices", "codes": ["BRVMC", "BRVM30"]}}, {"type": "piege", "titre": "Les fausses diversifications", "contenu": "Avoir beaucoup de lignes ne suffit pas.", "points": [{"titre": "Dix banques, un seul risque", "detail": "Dix lignes dans le même secteur réagissent ensemble à la même nouvelle.", "verifier": "La répartition par secteur de votre portefeuille."}, {"titre": "Des lignes trop petites", "detail": "Avec de petits montants, les frais minimum de courtage pèsent lourd sur chaque achat.", "verifier": "Le coût total d’un ordre chez votre SGI."}, {"titre": "Oublier la liquidité", "detail": "Certaines valeurs s’échangent peu : en cas de besoin, on peut ne pas réussir à vendre au prix affiché.", "verifier": "La classe de liquidité de chaque valeur."}, {"titre": "Ne jamais rééquilibrer", "detail": "Une ligne qui a beaucoup monté finit par peser trop lourd.", "verifier": "Le poids de chaque ligne, une fois par an."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Diversifier, c’est accepter de moins gagner sur sa meilleure idée pour ne pas tout perdre sur la pire.", "points": [{"titre": "La diversification réduit le risque propre, pas le risque de marché"}, {"titre": "Plusieurs secteurs et plusieurs pays valent mieux que beaucoup de lignes"}, {"titre": "Une ligne ne devrait pas dominer le portefeuille"}, {"titre": "Vérifier et rééquilibrer au moins une fois par an"}]}], "charts": [{"type": "line", "titre": "Risque d’un portefeuille selon le nombre de lignes (exemple)", "labels": ["1", "2", "4", "6", "8", "10", "15", "20"], "valeurs": [100, 74, 58, 52, 48, 46, 43, 42], "unite": "base 100", "note": "Valeurs d’exemple, pas des données de marché : risque du portefeuille, base 100 pour une seule action. La baisse est rapide pour les premières lignes, puis la courbe s’aplatit. Au-delà d’une quinzaine de lignes, il reste surtout le risque de marché, que la diversification ne supprime pas.", "reel": false}], "quiz": [{"question": "Quel risque la diversification ne peut-elle pas supprimer ?", "options": ["Le risque propre à une société", "Le risque de marché", "Le risque d’un mauvais résultat", "Le risque d’un litige"], "correct": 1, "explication": "Une crise générale touche toutes les actions : multiplier les lignes ne protège pas contre le risque de marché."}, {"question": "Un portefeuille compte dix lignes, toutes des banques. Est-il bien diversifié ?", "options": ["Oui, dix lignes suffisent", "Non, il reste exposé à un seul secteur", "Oui, à condition que ce soit dix pays différents", "La question n’a pas de sens"], "correct": 1, "explication": "Dix banques réagissent souvent ensemble aux mêmes nouvelles. La répartition par secteur compte autant que le nombre de lignes."}, {"question": "Pourquoi des lignes trop petites posent-elles problème ?", "options": ["Elles sont interdites", "Les frais minimum de courtage pèsent alors lourd sur chaque ordre", "Elles ne versent pas de dividende", "Elles augmentent le risque de marché"], "correct": 1, "explication": "Les frais de courtage comportent souvent un minimum : sur un petit ordre, ils représentent un pourcentage élevé."}, {"question": "Une ligne a beaucoup monté et pèse désormais 40 % du portefeuille. Que suggère le principe de diversification ?", "options": ["Ne rien faire", "Envisager de rééquilibrer pour réduire sa part", "Acheter encore la même valeur", "Vendre toutes les autres lignes"], "correct": 1, "explication": "Rééquilibrer ramène le portefeuille vers sa répartition cible et limite la dépendance à une seule société."}, {"question": "Pourquoi suivre l’indice BRVM Composite n’équivaut-il pas forcément à être diversifié ?", "options": ["Il ne contient qu’une société", "Il pondère par la capitalisation : quelques grandes valeurs pèsent lourd", "Il ne contient que des obligations", "Il n’existe plus"], "correct": 1, "explication": "Un indice pondéré par la capitalisation peut être dominé par quelques grandes sociétés."}], "liens": [{"label": "Mon portefeuille", "href": "/portefeuille"}, {"label": "La liquidité de chaque valeur", "href": "/liquidite"}, {"label": "Les secteurs", "href": "/secteurs"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "qcm": {"question": "Quel risque la diversification ne peut-elle pas supprimer ?", "options": ["Le risque propre à une société", "Le risque de marché", "Le risque d’un mauvais résultat", "Le risque d’un litige"], "correct": 1, "explication": "Une crise générale touche toutes les actions : multiplier les lignes ne protège pas contre le risque de marché."}}, {"titre": "Leçon 6 — Les droits préférentiels de souscription (DPS)", "module": "Module 2 — Construire son portefeuille", "categorie": "fundamental", "duree_min": 10, "sous_titre": "Quand une société augmente son capital, l’actionnaire en place reçoit un droit qui a une valeur. Le laisser expirer, c’est perdre de l’argent.", "resume": "Lors d’une augmentation de capital en numéraire, chaque action ancienne donne un droit préférentiel de souscription. Ce droit permet d’acheter des actions nouvelles à un prix réduit, ou se vend. Cette leçon explique le mécanisme, le calcul de sa valeur et les trois choix de l’actionnaire.", "sections": [{"type": "definition", "titre": "Pourquoi un droit préférentiel ?", "contenu": "Les actions nouvelles sont émises sous le cours de bourse pour attirer les souscripteurs. Sans protection, l’actionnaire en place verrait sa part diluée et la valeur de ses titres baisser.\nLe DPS compense cette perte : il donne la priorité aux anciens actionnaires, et il a une valeur négociable pendant la période de souscription.", "flux": [{"titre": "Annonce", "detail": "Prix d’émission et parité fixés", "icone": "decision"}, {"titre": "Détachement", "detail": "Un DPS par action ancienne", "icone": "calendrier"}, {"titre": "Souscription", "detail": "Exercer, vendre ou acheter des droits", "icone": "piece"}, {"titre": "Actions nouvelles", "detail": "Livrées, puis cotées", "icone": "actionnaires"}]}, {"type": "importance", "titre": "Calculer la valeur d’un droit", "contenu": "Exemple pédagogique : l’action cote 6 000 FCFA, la société émet 1 action nouvelle pour 4 anciennes à 4 500 FCFA.", "formules": [{"nom": "Valeur théorique du DPS", "expression": "(Cours − Prix d’émission) ÷ (Parité + 1)", "exemple": "(6 000 − 4 500) ÷ (4 + 1) = 300 FCFA par droit"}, {"nom": "Cours théorique après détachement", "expression": "Cours − Valeur du DPS", "exemple": "6 000 − 300 = 5 700 FCFA"}, {"nom": "Vérification", "expression": "(4 × 6 000 + 4 500) ÷ 5", "exemple": "28 500 ÷ 5 = 5 700 FCFA : la valeur se conserve"}]}, {"type": "cas", "titre": "Les trois choix de l’actionnaire", "contenu": "Exemple pédagogique : vous détenez 400 actions, donc 400 droits. Il faut 4 droits pour souscrire 1 action nouvelle.", "tableau": {"colonnes": ["Choix", "Ce que vous faites", "Résultat"], "lignes": [["Souscrire", "Exercer 400 droits et payer 100 × 4 500 FCFA", "500 actions ; votre part du capital est préservée"], ["Vendre les droits", "Céder 400 droits à environ 300 FCFA", "Environ 120 000 FCFA encaissés ; votre part est diluée"], ["Ne rien faire", "Laisser les droits expirer", "Perte d’environ 120 000 FCFA de valeur : à éviter"]], "note": "Les montants réels dépendent du cours du droit pendant la période de souscription, et des frais de votre SGI."}}, {"type": "importance", "titre": "Le calendrier d’une opération", "contenu": "Les dates sont fixées par l’avis publié par la BRVM. Elles comptent : un droit non exercé à la clôture perd toute valeur.", "etapes": [{"titre": "Avis de l’opération", "detail": "Prix d’émission, parité, dates de souscription, publiés par la BRVM et par la société."}, {"titre": "Détachement du droit", "detail": "Le cours de l’action s’ajuste ; le droit commence à se négocier.", "cle": true}, {"titre": "Période de souscription", "detail": "Vous transmettez votre choix à votre SGI : exercer, vendre, ou acheter des droits pour compléter."}, {"titre": "Clôture", "detail": "Les droits non exercés ni vendus ne valent plus rien."}, {"titre": "Livraison des actions nouvelles", "detail": "Elles s’ajoutent à votre compte-titres et deviennent négociables."}], "etapes_style": "frise"}, {"type": "piege", "titre": "Les erreurs à éviter", "contenu": "Les DPS sont rares, et c’est justement pour cela qu’on se trompe.", "points": [{"titre": "Ignorer le courrier de sa SGI", "detail": "Sans instruction de votre part, les droits peuvent expirer.", "verifier": "La date de clôture de la souscription."}, {"titre": "Croire que le cours a « chuté »", "detail": "Le jour du détachement, la baisse du cours correspond à la valeur du droit : ce n’est pas une perte.", "verifier": "La valeur théorique du DPS."}, {"titre": "Souscrire sans comprendre l’opération", "detail": "Une augmentation de capital peut financer un projet, ou combler des pertes. Ce n’est pas la même chose.", "verifier": "L’objet de l’opération dans la note d’information."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Un DPS a toujours une valeur tant que la souscription est ouverte.", "points": [{"titre": "Valeur théorique = (cours − prix d’émission) ÷ (parité + 1)"}, {"titre": "Trois choix : souscrire, vendre, ou acheter des droits pour compléter"}, {"titre": "Ne rien faire revient à perdre la valeur du droit"}, {"titre": "Lire l’objet de l’augmentation de capital avant de souscrire"}]}], "quiz": [{"question": "Une action cote 8 000 FCFA. La société émet 1 action nouvelle pour 3 anciennes à 6 000 FCFA. Quelle est la valeur théorique du DPS ?", "options": ["250 FCFA", "500 FCFA", "667 FCFA", "2 000 FCFA"], "correct": 1, "explication": "(8 000 − 6 000) ÷ (3 + 1) = 500 FCFA."}, {"question": "Dans le même exemple, quel est le cours théorique après détachement ?", "options": ["6 000 FCFA", "7 500 FCFA", "8 000 FCFA", "8 500 FCFA"], "correct": 1, "explication": "8 000 − 500 = 7 500 FCFA. Vérification : (3 × 8 000 + 6 000) ÷ 4 = 7 500."}, {"question": "Que se passe-t-il si vous ne faites rien de vos droits ?", "options": ["Ils sont automatiquement exercés", "Ils expirent sans valeur à la clôture", "Ils se transforment en dividende", "Ils sont remboursés au nominal"], "correct": 1, "explication": "Un droit non exercé et non vendu à la clôture perd toute valeur."}, {"question": "Le jour du détachement, le cours baisse d’un montant proche de la valeur du droit. Est-ce une perte pour l’actionnaire ?", "options": ["Oui, une perte définitive", "Non : cette baisse est compensée par la valeur du droit reçu", "Oui, sauf si le dividende est maintenu", "Non, le cours ne bouge jamais"], "correct": 1, "explication": "La valeur se répartit entre l’action ex-droit et le droit. L’actionnaire ne s’appauvrit que s’il laisse le droit expirer."}, {"question": "Pourquoi lire l’objet d’une augmentation de capital avant de souscrire ?", "options": ["Ce n’est pas utile", "Financer un projet de croissance et combler des pertes ne présentent pas le même risque", "Pour connaître la couleur du logo", "Pour connaître le nom de la SGI"], "correct": 1, "explication": "L’usage des fonds levés dit beaucoup sur la situation de la société."}], "liens": [{"label": "Les opérations sur titres", "href": "/operations-titres"}, {"label": "L’agenda du marché", "href": "/calendrier"}, {"label": "Mon portefeuille", "href": "/portefeuille"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Une action cote 8 000 FCFA. La société émet 1 action nouvelle pour 3 anciennes à 6 000 FCFA. Quelle est la valeur théorique du DPS ?", "options": ["250 FCFA", "500 FCFA", "667 FCFA", "2 000 FCFA"], "correct": 1, "explication": "(8 000 − 6 000) ÷ (3 + 1) = 500 FCFA."}}, {"titre": "Leçon 7 — Simulation de portefeuille sur 3 ans", "module": "Module 2 — Construire son portefeuille", "categorie": "income", "duree_min": 12, "sous_titre": "Faire tourner des hypothèses avant d’engager son argent : dividendes réinvestis, objectif de revenu, et ce que les chiffres ne disent pas.", "resume": "Une simulation ne prédit rien : elle montre l’effet de vos hypothèses. Cette leçon calcule le réinvestissement des dividendes sur trois ans, l’argent nécessaire pour viser un revenu, et propose de tester une stratégie sans risque avec le portefeuille virtuel.", "sections": [{"type": "definition", "titre": "Ce qu’une simulation est, et n’est pas", "contenu": "Une simulation applique des hypothèses : un dividende, une croissance, un cours. Si une hypothèse change, le résultat change.\nElle sert à comparer des scénarios et à comprendre un mécanisme. Elle ne garantit aucun résultat.", "points": [{"titre": "Elle aide à", "detail": "Mesurer l’effet du réinvestissement, comparer des rendements, fixer un ordre de grandeur."}, {"titre": "Elle ne dit pas", "detail": "Ce que fera le cours, si le dividende sera maintenu, ni ce que coûteront les frais et l’impôt dans votre situation."}]}, {"type": "cas", "titre": "Réinvestir ses dividendes pendant 3 ans", "contenu": "Hypothèses pédagogiques : 200 actions, un dividende net de 900 FCFA par action qui progresse de 3 % par an, un cours constant de 15 000 FCFA. Les dividendes servent à racheter des actions. Le calcul est fait à l’affichage, à partir de ces seules hypothèses.", "simulation": {"type": "reinvestissement", "actions": 200, "dpa": 900, "cours": 15000, "croissance_pct": 3, "annees": 3}}, {"type": "cas", "titre": "Combien investir pour viser un revenu ?", "contenu": "Hypothèse pédagogique : vous visez 600 000 FCFA de dividendes nets par an. La somme nécessaire dépend du rendement retenu. Plus le rendement visé est élevé, plus le risque d’un dividende réduit l’est aussi.", "simulation": {"type": "objectif", "revenu_cible": 600000, "rendements_pct": [5, 7, 9]}}, {"type": "importance", "titre": "Trois portefeuilles d’exemple", "contenu": "Trois répartitions pédagogiques de 3 000 000 FCFA, sans aucune valeur citée : elles illustrent des profils, pas des recommandations.", "tableau": {"colonnes": ["Profil", "Répartition", "Ce qu’il cherche", "Ce qu’il accepte"], "lignes": [["Prudent", "Moitié obligations, moitié actions à dividende régulier", "Des revenus stables", "Une croissance plus lente"], ["Équilibré", "Un quart d’obligations, trois quarts d’actions de 4 secteurs", "Revenus et croissance", "Des baisses temporaires"], ["Dynamique", "Actions seulement, 8 à 12 lignes", "La croissance du capital", "De fortes variations"]], "note": "Exemples pédagogiques. La bonne répartition dépend de votre horizon, de vos besoins et de votre tolérance aux pertes."}}, {"type": "importance", "titre": "Tester sans risque", "contenu": "Le portefeuille virtuel de WestBourse permet d’acheter et de vendre aux cours réels, sans engager d’argent. C’est le meilleur moyen de vérifier qu’une stratégie tient sur la durée, et de connaître ses propres réactions face à une baisse.", "etapes": [{"titre": "Définir le profil et la somme", "detail": "Par exemple 3 000 000 FCFA, profil équilibré."}, {"titre": "Composer le portefeuille virtuel", "detail": "En respectant les repères de diversification de la leçon 5."}, {"titre": "Le suivre trois mois", "detail": "Noter ses réactions aux baisses, et l’arrivée des dividendes.", "cle": true}, {"titre": "Comparer à l’indice", "detail": "Le portefeuille fait-il mieux, ou moins bien, que le marché ?"}]}, {"type": "piege", "titre": "Les illusions des simulations", "contenu": "Les chiffres d’une simulation sont toujours plus propres que la réalité.", "points": [{"titre": "Oublier les frais et l’impôt", "detail": "Les frais de courtage et la retenue sur les dividendes réduisent le résultat réel.", "verifier": "Si le dividende simulé est brut ou net."}, {"titre": "Supposer un cours constant", "detail": "Le cours peut baisser ; réinvestir à un cours plus bas achète alors plus d’actions, mais le capital affiché diminue.", "verifier": "Le résultat dans un scénario défavorable."}, {"titre": "Extrapoler le passé", "detail": "Une croissance de dividende passée n’est pas une promesse.", "verifier": "La régularité du dividende sur cinq ans."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Simuler, c’est rendre ses hypothèses visibles.", "points": [{"titre": "Une simulation compare des scénarios, elle ne prédit pas"}, {"titre": "Le réinvestissement des dividendes accélère la croissance du nombre d’actions"}, {"titre": "Un rendement visé plus élevé demande moins de capital, et plus de risque"}, {"titre": "Le portefeuille virtuel teste une stratégie sans engager d’argent"}]}], "quiz": [{"question": "Pour viser 400 000 FCFA de dividendes par an avec un rendement de 8 %, quelle somme faut-il investir ?", "options": ["3 200 000 FCFA", "5 000 000 FCFA", "8 000 000 FCFA", "32 000 000 FCFA"], "correct": 1, "explication": "400 000 ÷ 0,08 = 5 000 000 FCFA."}, {"question": "Vous détenez 100 actions à 10 000 FCFA ; le dividende est de 600 FCFA, entièrement réinvesti au même cours. Combien d’actions achetez-vous ?", "options": ["3", "6", "10", "60"], "correct": 1, "explication": "100 × 600 = 60 000 FCFA, soit 6 actions à 10 000 FCFA."}, {"question": "Qu’est-ce qu’une simulation ne peut pas faire ?", "options": ["Comparer deux scénarios", "Garantir le résultat futur", "Montrer l’effet du réinvestissement", "Donner un ordre de grandeur"], "correct": 1, "explication": "Une simulation applique des hypothèses ; elle ne garantit rien."}, {"question": "Pourquoi viser un rendement très élevé augmente-t-il le risque ?", "options": ["Ce n’est pas le cas", "Les rendements très élevés vont souvent avec des dividendes fragiles ou des cours en baisse", "Les frais sont plus élevés", "L’impôt est plus élevé"], "correct": 1, "explication": "Un rendement élevé peut annoncer un dividende réduit. Il faut vérifier sa régularité."}, {"question": "À quoi sert le portefeuille virtuel ?", "options": ["À investir de l’argent réel sans frais", "À tester une stratégie aux cours réels, sans engager d’argent", "À obtenir des dividendes gratuits", "À éviter l’impôt"], "correct": 1, "explication": "Il reproduit les achats et ventes aux cours réels, sans argent engagé."}], "liens": [{"label": "Le portefeuille virtuel", "href": "/premium/paper-trading"}, {"label": "Le simulateur", "href": "/simulateur"}, {"label": "Les dividendes", "href": "/dividendes"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Pour viser 400 000 FCFA de dividendes par an avec un rendement de 8 %, quelle somme faut-il investir ?", "options": ["3 200 000 FCFA", "5 000 000 FCFA", "8 000 000 FCFA", "32 000 000 FCFA"], "correct": 1, "explication": "400 000 ÷ 0,08 = 5 000 000 FCFA."}}, {"titre": "Leçon 8 — La fiscalité des revenus boursiers", "module": "Module 3 — Thèmes avancés", "categorie": "income", "duree_min": 9, "sous_titre": "Ce que l’impôt retient sur un dividende ou un coupon, selon le pays de la société, et comment lire un montant « net ».", "resume": "À la BRVM, l’impôt sur les dividendes est retenu à la source par la société, selon la loi de son pays : c’est l’IRVM. Le taux varie d’un pays à l’autre. Cette leçon montre les taux que WestBourse a vérifiés, la différence entre brut et net, et le cas des obligations.", "sections": [{"type": "definition", "titre": "L’impôt est retenu avant le versement", "contenu": "L’impôt sur le revenu des valeurs mobilières (IRVM) est prélevé par la société au moment du paiement. Vous recevez le dividende net : vous n’avez rien à verser vous-même pour cet impôt.\nLe taux dépend de la législation du pays de la société qui verse, pas de la SGI.", "formules": [{"nom": "Dividende net", "expression": "Dividende brut × (1 − taux d’IRVM)", "exemple": "1 000 × (1 − 12 %) = 880 FCFA"}, {"nom": "Rendement net", "expression": "Dividende net ÷ Cours", "exemple": "880 ÷ 16 000 = 5,5 %"}]}, {"type": "importance", "titre": "Les taux sur les dividendes d’actions cotées", "contenu": "Taux applicables aux personnes physiques, tels que WestBourse les a vérifiés. Ils changent avec les lois de finances : la page Fiscalité du site fait foi et cite ses sources.", "tableau": {"colonnes": ["Pays de la société", "Taux sur les dividendes", "Précision"], "lignes": [["Côte d’Ivoire", "12 %", "10 % pour les personnes morales, depuis l’annexe fiscale 2025"], ["Sénégal", "10 %", "—"], ["Burkina Faso", "12,5 %", "—"], ["Mali", "7 %", "Taux en vigueur depuis 2017"], ["Bénin", "5 %", "Taux réduit en vigueur depuis 2018"], ["Togo", "3 %", "Personnes physiques ; 7 % pour les personnes morales"], ["Niger, Guinée-Bissau", "Non vérifié", "WestBourse n’affiche pas de taux tant qu’il n’est pas confirmé"]], "note": "Source : barème WestBourse (page Fiscalité), constitué à partir de sources publiques citées sur cette page."}}, {"type": "importance", "titre": "Les obligations", "contenu": "Les coupons des titres émis par les États de l’UEMOA et par les institutions régionales comme la BOAD ou la BIDC sont en principe exonérés. Les obligations de sociétés privées supportent une retenue, dont le taux varie selon le pays.\nC’est l’une des raisons pour lesquelles une obligation d’État peut rapporter plus, net, qu’un placement affiché à un taux supérieur."}, {"type": "piege", "titre": "Les confusions fréquentes", "contenu": "La plupart des erreurs viennent d’un mélange entre brut et net.", "points": [{"titre": "Retirer l’impôt deux fois", "detail": "Le calendrier officiel des dividendes de la BRVM publie souvent des montants déjà nets. Leur appliquer à nouveau l’IRVM sous-estime le rendement.", "verifier": "La mention brut ou net du montant."}, {"titre": "Appliquer le taux de son propre pays", "detail": "C’est le pays de la société qui verse qui détermine la retenue.", "verifier": "Le pays de la société sur sa fiche."}, {"titre": "Oublier sa situation personnelle", "detail": "Résidence fiscale, investissement depuis l’étranger, compte d’entreprise : votre SGI ou un conseiller fiscal tranche.", "verifier": "Votre relevé de dividendes chez votre SGI."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Toujours savoir si un montant est brut ou net.", "points": [{"titre": "L’IRVM est retenu à la source, selon le pays de la société"}, {"titre": "Les taux sur les dividendes vont de 3 % à 12,5 % selon les pays vérifiés"}, {"titre": "Les titres d’État et des institutions régionales sont en principe exonérés"}, {"titre": "Ne pas retirer l’impôt d’un montant déjà net"}]}], "quiz": [{"question": "Une société ivoirienne verse un dividende brut de 1 500 FCFA. Avec un IRVM de 12 %, quel est le dividende net ?", "options": ["1 200 FCFA", "1 320 FCFA", "1 380 FCFA", "1 500 FCFA"], "correct": 1, "explication": "1 500 × (1 − 0,12) = 1 320 FCFA."}, {"question": "Qui retient l’IRVM sur un dividende ?", "options": ["L’actionnaire, dans sa déclaration annuelle", "La société, au moment du versement", "La BRVM, à la fin de l’année", "Personne"], "correct": 1, "explication": "L’IRVM est une retenue à la source : la société le prélève avant de verser le dividende net."}, {"question": "Quel pays détermine le taux d’IRVM d’un dividende ?", "options": ["Le pays de l’investisseur", "Le pays de la société qui verse le dividende", "Le pays de la SGI", "Le pays de la banque de l’investisseur"], "correct": 1, "explication": "La retenue suit la législation du pays de la société émettrice."}, {"question": "Un montant publié est déjà net d’impôt. Que se passe-t-il si vous lui retirez encore l’IRVM ?", "options": ["Rien", "Vous sous-estimez votre revenu et votre rendement", "Vous surestimez votre revenu", "Vous payez deux fois l’impôt"], "correct": 1, "explication": "Retirer l’impôt d’un montant déjà net donne un revenu calculé trop bas."}, {"question": "Les coupons des obligations d’État de l’UEMOA sont :", "options": ["Imposés au même taux que les dividendes", "En principe exonérés", "Imposés à 50 %", "Interdits aux particuliers"], "correct": 1, "explication": "Les titres publics des États et des institutions régionales sont en principe exonérés."}], "liens": [{"label": "La fiscalité par pays", "href": "/fiscalite"}, {"label": "Le calendrier des dividendes", "href": "/dividendes/calendrier"}, {"label": "Les dividendes", "href": "/dividendes"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Une société ivoirienne verse un dividende brut de 1 500 FCFA. Avec un IRVM de 12 %, quel est le dividende net ?", "options": ["1 200 FCFA", "1 320 FCFA", "1 380 FCFA", "1 500 FCFA"], "correct": 1, "explication": "1 500 × (1 − 0,12) = 1 320 FCFA."}}, {"titre": "Leçon 9 — Les obligations cotées à la BRVM", "module": "Module 3 — Thèmes avancés", "categorie": "income", "duree_min": 11, "sous_titre": "Prêter à un État ou à une entreprise, recevoir un coupon, être remboursé : le fonctionnement et les pièges d’un marché peu liquide.", "resume": "Une obligation est un prêt découpé en titres. L’émetteur verse un intérêt, le coupon, et rembourse le capital selon un calendrier fixé. La BRVM cote plus de deux cents emprunts, surtout d’États. Cette leçon explique le vocabulaire, le calcul du rendement et les précautions propres à ce marché.", "sections": [{"type": "definition", "titre": "Le vocabulaire d’une obligation", "contenu": "Toutes les informations figurent dans la note d’information de l’emprunt.", "points": [{"titre": "Le nominal", "detail": "La valeur d’un titre, souvent 10 000 FCFA à la BRVM. Le coupon se calcule sur ce montant."}, {"titre": "Le taux nominal (coupon)", "detail": "L’intérêt annuel, en pourcentage du nominal. Un titre de 10 000 FCFA à 6 % rapporte 600 FCFA par an avant impôt."}, {"titre": "La maturité", "detail": "La date du dernier remboursement. Au-delà, le titre n’existe plus."}, {"titre": "L’amortissement", "detail": "In fine : tout le capital est rendu à la fin. Constant : une part est rendue chaque année, souvent après un différé."}]}, {"type": "importance", "titre": "Prix, coupon couru et rendement", "contenu": "Le prix d’une obligation varie : il baisse quand les taux du marché montent, et monte quand ils baissent. Le rendement réel dépend donc du prix payé. Exemples pédagogiques.", "formules": [{"nom": "Coupon annuel", "expression": "Nominal × Taux nominal", "exemple": "10 000 × 6,5 % = 650 FCFA par an"}, {"nom": "Rendement courant", "expression": "Coupon annuel ÷ Prix payé", "exemple": "650 ÷ 9 800 = 6,6 %"}, {"nom": "Coupon couru", "expression": "Coupon × Jours écoulés ÷ 365", "exemple": "Payé en plus du prix à l’achat, rendu au prochain coupon"}]}, {"type": "cas", "titre": "Un emprunt amorti : exemple", "contenu": "Exemple pédagogique : 100 titres de 10 000 FCFA à 6 %, sur 5 ans, avec remboursement constant du capital chaque année. Le coupon baisse à mesure que le capital restant diminue.", "tableau": {"colonnes": ["Année", "Capital restant dû", "Coupon (6 %)", "Capital remboursé", "Total reçu"], "lignes": [["1", "1 000 000", "60 000", "200 000", "260 000"], ["2", "800 000", "48 000", "200 000", "248 000"], ["3", "600 000", "36 000", "200 000", "236 000"], ["4", "400 000", "24 000", "200 000", "224 000"], ["5", "200 000", "12 000", "200 000", "212 000"]], "note": "Montants en FCFA, avant impôt. Sur cinq ans : 180 000 FCFA de coupons et le million rendu."}}, {"type": "importance", "titre": "Les risques d’une obligation", "contenu": "Une obligation est moins risquée qu’une action, pas sans risque.", "points": [{"titre": "Le risque de défaut", "detail": "L’émetteur peut payer en retard ou ne pas rembourser. Un État n’est pas à l’abri d’un rééchelonnement.", "verifier": "La notation de l’émetteur, quand elle existe."}, {"titre": "Le risque de taux", "detail": "Si les taux montent, le prix d’une obligation déjà émise baisse avant l’échéance.", "verifier": "La durée restante : plus elle est longue, plus le prix est sensible."}, {"titre": "Le risque de liquidité", "detail": "Beaucoup d’obligations s’échangent rarement. Revendre avant l’échéance peut prendre du temps, ou coûter une décote.", "verifier": "Les volumes échangés récemment."}]}, {"type": "piege", "titre": "Les pièges propres à la BRVM", "contenu": "Quelques réflexes évitent des erreurs coûteuses.", "points": [{"titre": "Un cours affiché n’est pas une transaction", "detail": "Sans échange, le cours d’une obligation reste souvent au pair pendant des mois. Il ne dit rien du prix auquel vous pourriez vendre.", "verifier": "La date du dernier échange réel."}, {"titre": "Un titre listé peut être échu", "detail": "Des emprunts arrivés à échéance depuis des années restent parfois affichés sur les listes publiques. WestBourse les retire de ses tableaux.", "verifier": "La date de maturité."}, {"titre": "Confondre taux nominal et rendement", "detail": "Acheter au-dessus du pair réduit le rendement réel sous le taux affiché.", "verifier": "Le prix payé, coupon couru compris."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Une obligation se juge à quatre éléments.", "points": [{"titre": "Qui emprunte, et sa capacité à rembourser"}, {"titre": "Le taux, comparé au prix payé"}, {"titre": "Le calendrier de remboursement : in fine ou amorti"}, {"titre": "La liquidité : pourrez-vous revendre avant l’échéance ?"}]}], "charts": [{"type": "bar", "titre": "Ce que verse un emprunt amorti, année par année (exemple)", "labels": ["Année 1", "Année 2", "Année 3", "Année 4", "Année 5"], "valeurs": [260000, 248000, 236000, 224000, 212000], "unite": "FCFA", "note": "Exemple pédagogique : 1 000 000 FCFA prêtés à 6 % sur 5 ans, capital remboursé par cinquièmes. Le total reçu baisse chaque année, parce que le coupon se calcule sur un capital restant de plus en plus petit.", "reel": false}], "quiz": [{"question": "Une obligation de nominal 10 000 FCFA verse un coupon de 7 %. Combien rapporte-t-elle par an, avant impôt ?", "options": ["70 FCFA", "700 FCFA", "7 000 FCFA", "10 700 FCFA"], "correct": 1, "explication": "10 000 × 7 % = 700 FCFA."}, {"question": "Vous achetez cette obligation 10 500 FCFA. Son rendement courant est-il supérieur ou inférieur à 7 % ?", "options": ["Supérieur", "Inférieur", "Égal", "Impossible à dire"], "correct": 1, "explication": "700 ÷ 10 500 ≈ 6,7 % : payer au-dessus du pair réduit le rendement."}, {"question": "Que se passe-t-il pour le prix d’une obligation existante quand les taux du marché montent ?", "options": ["Il monte", "Il baisse", "Il ne bouge pas", "Le coupon augmente"], "correct": 1, "explication": "Les nouvelles émissions rapportent plus : le prix des anciennes baisse pour s’aligner."}, {"question": "Dans un emprunt à amortissement constant, le coupon versé chaque année :", "options": ["Augmente", "Diminue, car le capital restant diminue", "Reste identique", "Est nul"], "correct": 1, "explication": "Le coupon se calcule sur le capital restant dû, qui baisse à chaque remboursement."}, {"question": "Une obligation affiche le même cours depuis des mois. Qu’en conclure ?", "options": ["Que le titre est très stable", "Qu’il s’échange peut-être très peu : vérifier la date du dernier échange réel", "Qu’il va bientôt monter", "Qu’il est garanti par l’État"], "correct": 1, "explication": "Sans échange, le cours affiché ne bouge pas. Ce n’est pas un prix auquel on est sûr de vendre."}], "liens": [{"label": "Le marché obligataire", "href": "/obligations"}, {"label": "La fiscalité par pays", "href": "/fiscalite"}, {"label": "L’agenda du marché", "href": "/calendrier"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "qcm": {"question": "Une obligation de nominal 10 000 FCFA verse un coupon de 7 %. Combien rapporte-t-elle par an, avant impôt ?", "options": ["70 FCFA", "700 FCFA", "7 000 FCFA", "10 700 FCFA"], "correct": 1, "explication": "10 000 × 7 % = 700 FCFA."}}, {"titre": "Leçon 10 — Les OPCVM : investir par des fonds collectifs", "module": "Module 3 — Thèmes avancés", "categorie": "general", "duree_min": 9, "sous_titre": "Confier son épargne à un gérant professionnel : comment fonctionnent les FCP et les SICAV, ce qu’ils coûtent, et comment les comparer.", "resume": "Un OPCVM réunit l’argent de nombreux épargnants et l’investit en actions, en obligations ou en placements monétaires. Il est géré par une société de gestion agréée par l’AMF-UMOA. Cette leçon explique la valeur liquidative, les frais, les catégories de fonds et les questions à poser avant de souscrire.", "sections": [{"type": "definition", "titre": "Le principe", "contenu": "Vous achetez des parts du fonds. Le gérant investit l’ensemble selon une politique écrite dans le prospectus. La valeur de vos parts suit celle des placements du fonds.", "flux": [{"titre": "Épargnants", "detail": "Achètent des parts", "icone": "actionnaires"}, {"titre": "Société de gestion", "detail": "Agréée, décide des placements", "icone": "decision"}, {"titre": "Placements", "detail": "Actions, obligations, monétaire", "icone": "graphique"}, {"titre": "Valeur liquidative", "detail": "Prix d’une part, publié régulièrement", "icone": "piece"}]}, {"type": "importance", "titre": "FCP et SICAV, et leurs acteurs", "contenu": "Les deux formes coexistent dans l’UEMOA, sous le contrôle de l’AMF-UMOA, qui a succédé au CREPMF.", "tableau": {"colonnes": ["Critère", "FCP", "SICAV"], "lignes": [["Nature", "Copropriété de titres, sans personnalité juridique", "Société anonyme dont on devient actionnaire"], ["Gestion", "Une société de gestion d’OPCVM agréée", "La SICAV elle-même, ou un gérant délégué"], ["Conservation", "Un dépositaire, en général une banque", "Un dépositaire, en général une banque"], ["Pour l’épargnant", "Achat et vente de parts à la valeur liquidative", "Achat et vente d’actions de la SICAV à la valeur liquidative"]], "note": "Dans les deux cas, le dépositaire conserve les actifs : ils sont séparés de ceux de la société de gestion."}}, {"type": "importance", "titre": "Ce que coûte un fonds", "contenu": "Les frais réduisent directement la performance. Ils figurent dans le prospectus. Exemple pédagogique sur 1 000 000 FCFA.", "formules": [{"nom": "Frais d’entrée", "expression": "Somme investie × taux d’entrée", "exemple": "1 000 000 × 2 % = 20 000 FCFA prélevés dès la souscription"}, {"nom": "Frais de gestion annuels", "expression": "Encours × taux de gestion", "exemple": "1 000 000 × 1,5 % = 15 000 FCFA par an"}, {"nom": "Valeur liquidative", "expression": "Actif net du fonds ÷ Nombre de parts", "exemple": "5 Md ÷ 500 000 parts = 10 000 FCFA la part"}]}, {"type": "cas", "titre": "Les grandes familles de fonds", "contenu": "La politique d’investissement détermine le risque.", "points": [{"titre": "Monétaire", "detail": "Placements très courts. Faible risque, faible rendement, disponibilité rapide."}, {"titre": "Obligataire", "detail": "Surtout des obligations. Revenus réguliers, sensibles aux taux."}, {"titre": "Diversifié", "detail": "Un mélange d’actions et d’obligations, selon des bornes fixées par le prospectus."}, {"titre": "Actions", "detail": "Surtout des actions de la BRVM. Le potentiel et les variations les plus forts."}]}, {"type": "piege", "titre": "Les questions à poser avant de souscrire", "contenu": "Un fonds se choisit sur des faits écrits, pas sur une promesse.", "points": [{"titre": "Le fonds est-il agréé ?", "detail": "Un OPCVM doit être agréé par l’AMF-UMOA.", "verifier": "La liste publiée par l’AMF-UMOA."}, {"titre": "Quels sont tous les frais ?", "detail": "Entrée, sortie, gestion : additionnez-les sur votre horizon.", "verifier": "Le prospectus."}, {"titre": "Quelle performance, sur quelle durée, comparée à quoi ?", "detail": "Une bonne année isolée ne prouve rien.", "verifier": "La performance sur trois à cinq ans, comparée à un indice."}, {"titre": "Méfiance devant un rendement garanti élevé", "detail": "Un fonds investi en actions ne peut pas garantir un rendement élevé.", "verifier": "Le mot « garanti » dans le document officiel."}]}, {"type": "retenir", "titre": "L’essentiel", "contenu": "Un OPCVM délègue le choix des titres, pas la responsabilité de choisir le fonds.", "points": [{"titre": "Une société de gestion agréée investit, un dépositaire conserve"}, {"titre": "La valeur liquidative est le prix d’une part"}, {"titre": "Les frais réduisent directement la performance"}, {"titre": "Vérifier l’agrément et la performance sur plusieurs années"}]}], "quiz": [{"question": "Un fonds a un actif net de 2 milliards de FCFA et 400 000 parts. Quelle est sa valeur liquidative ?", "options": ["500 FCFA", "5 000 FCFA", "50 000 FCFA", "800 FCFA"], "correct": 1, "explication": "2 000 000 000 ÷ 400 000 = 5 000 FCFA par part."}, {"question": "Vous investissez 2 000 000 FCFA avec 3 % de frais d’entrée. Combien est réellement investi ?", "options": ["1 400 000 FCFA", "1 940 000 FCFA", "2 000 000 FCFA", "2 060 000 FCFA"], "correct": 1, "explication": "2 000 000 × 3 % = 60 000 FCFA de frais ; 1 940 000 FCFA sont investis."}, {"question": "Qui conserve les actifs d’un OPCVM ?", "options": ["Le gérant, sur son propre compte", "Un dépositaire, en général une banque", "La BRVM", "Chaque épargnant"], "correct": 1, "explication": "Le dépositaire conserve les actifs, séparés de ceux de la société de gestion."}, {"question": "Quelle autorité agrée les OPCVM dans l’UEMOA ?", "options": ["La BCEAO", "L’AMF-UMOA", "La BRVM", "Chaque SGI"], "correct": 1, "explication": "L’AMF-UMOA, qui a succédé au CREPMF, agrée et contrôle les OPCVM et leurs sociétés de gestion."}, {"question": "Un fonds investi en actions promet un rendement « garanti » de 15 % par an. Quelle est la bonne réaction ?", "options": ["Souscrire vite", "Se méfier : un fonds actions ne peut pas garantir un rendement élevé", "Négocier les frais", "Demander 20 %"], "correct": 1, "explication": "La valeur d’un fonds actions suit le marché : aucun rendement élevé ne peut y être garanti."}], "liens": [{"label": "Le marché obligataire", "href": "/obligations"}, {"label": "Les secteurs", "href": "/secteurs"}, {"label": "Le simulateur", "href": "/simulateur"}], "avertissement": "Ceci n’est pas un conseil en investissement. Les ratios décrivent le passé et ne garantissent aucune performance future. Investir en actions comporte un risque de perte en capital.", "charts": [], "qcm": {"question": "Un fonds a un actif net de 2 milliards de FCFA et 400 000 parts. Quelle est sa valeur liquidative ?", "options": ["500 FCFA", "5 000 FCFA", "50 000 FCFA", "800 FCFA"], "correct": 1, "explication": "2 000 000 000 ÷ 400 000 = 5 000 FCFA par part."}}]$wb$::jsonb), '{intro}', to_jsonb($wb$Niveau 2 — Analyse fondamentale. Dix leçons pour lire les comptes d’une société cotée, l’évaluer avec ses ratios, analyser une banque, puis construire et simuler un portefeuille ; trois leçons finales sur la fiscalité, les obligations et les OPCVM. Les chiffres de marché sont lus en base à l’ouverture de chaque leçon ; les exemples chiffrés sont pédagogiques et annoncés comme tels.$wb$::text)),
         updated_at = now()
   where id = v_id;
